  const p = join(__dirname, '/write-then-end')

  const check = t => {
    t.equal(fs.readFileSync(p, 'utf8'), 'okend')
    fs.unlinkSync(p)
    t.end()
  }

  t.test('sync', t => {
    const s = new fsm.WriteStreamSync(p)
    s.write('ok')
    s.end('end')
    check(t)
  })

  t.test('async', t => {
    const s = new fsm.WriteStream(p)
    s.write('ok')
    s.end('end')
    t.equal(s.fd, null)
    t.equal(s.path, p)
    s.on('open', fd => {
      t.equal(fd, s.fd)
      t.type(fd, 'number')
    })
    s.on('finish', _ => check(t))
  })

  t.end()
})

